// Общие шаги для тестов «דייט עכשיו» (#1fd43a): геолокация, вкл/выкл Date Now (только Premium user2), временное расширение возрастных фильтров.
// Написано вручную (несколько ролей), селекторы — по скриншотам ручной проверки 01–02.11; не прогонялось — проверить при первом /qa-regress.
import { expect, type Page, type Response } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { captureApi, restGet, type Api, type Row } from '../_shared/api';
import { fetchNearby, rowId, type NearbyRow } from '../location-map/map-helpers';

export const DN_GEO = {
  reg1: { latitude: 32.07, longitude: 34.79 },
  reg4: { latitude: 32.0715, longitude: 34.7884 }, // ~225 м от reg1
  user2: { latitude: 32.087, longitude: 34.79 }, // ~1.9 км от reg1
  jerusalem: { latitude: 31.7767, longitude: 35.2345 },
} as const;

export const NAMES = { user2: 'QA דתי', reg4: 'QA לייק 1', reg1: 'QA הרשמה' } as const;

// iPhone 390×844 + эмулированная геолокация (реальная не используется).
export async function setupGeo(page: Page, where: keyof typeof DN_GEO) {
  await page.setViewportSize({ width: 390, height: 844 });
  const cfg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../qa.config.json'), 'utf8'));
  const origin = new URL(process.env.QA_BASE_URL || cfg.baseUrl).origin;
  await page.context().grantPermissions(['geolocation'], { origin });
  await page.context().setGeolocation({ ...DN_GEO[where], accuracy: 10 });
}

const isSetDateNow = (r: Response) => r.url().includes('/rpc/set_date_now') && r.request().method() === 'POST';
const timerPill = (page: Page) => page.getByText(/דייט עכשיו\s*•\s*\d+:\d{2}/);
const dnButton = (page: Page) => page.getByRole('button', { name: /דייט עכשיו/ }).first();

// Включить Date Now на 30 минут (только для Premium — у бесплатных тратит недельное окно!). Шаринг должен быть включён.
export async function enableDateNow30(page: Page) {
  if (await timerPill(page).isVisible()) return;
  await dnButton(page).click();
  const sheet = page.getByRole('dialog').filter({ hasText: 'פנוי/ה לדייט עכשיו?' });
  await expect(sheet).toBeVisible();
  await sheet.getByText('30 דק׳', { exact: true }).click();
  const res = page.waitForResponse(isSetDateNow);
  await sheet.getByRole('button', { name: /^להפעיל/ }).click();
  expect((await res).ok(), 'set_date_now (вкл.)').toBeTruthy();
  await expect(timerPill(page)).toBeVisible();
}

// Выключить Date Now: плашка с таймером → шит «דייט עכשיו פעיל» → «לכבות». Безопасно, если уже выключен.
export async function disableDateNow(page: Page) {
  if (page.isClosed()) return;
  await page.goto('/map');
  await expect(dnButton(page)).toBeVisible();
  if (!(await timerPill(page).isVisible())) return;
  await timerPill(page).click();
  await expect(page.getByText('דייט עכשיו פעיל')).toBeVisible();
  const res = page.waitForResponse(isSetDateNow);
  await page.getByRole('button', { name: 'לכבות' }).click();
  expect((await res).ok(), 'set_date_now (выкл.)').toBeTruthy();
  await expect(timerPill(page)).toHaveCount(0);
}

// Найти строку пользователя в nearby_live и его позицию.
export const findRow = (rows: NearbyRow[], id: string) => ({ idx: rows.findIndex((r) => rowId(r) === id), row: rows.find((r) => rowId(r) === id) });

// Опрос nearby_live у page до выполнения условия (без фиксированных пауз; у других изменения видны с задержкой опроса, #0f19c0).
export async function pollNearby(page: Page, cond: (rows: NearbyRow[]) => boolean, message: string, timeout = 60_000) {
  let last: NearbyRow[] = [];
  await expect
    .poll(async () => cond((last = await fetchNearby(page))), { message, timeout, intervals: [2_000, 3_000, 5_000] })
    .toBe(true);
  return last;
}

// ---- Возрастные фильтры (временное расширение — разрешено пользователем 02.11 для AC 5; вернуть в finally) ----
// Колонки ищутся по имени (age + min/max/from/to) в строке profiles пользователя; исходные значения возвращаются как были.
export type AgePrefs = { api: Api; original: Row };

function ageKeys(row: Row) {
  const keys = Object.keys(row).filter((k) => /age/i.test(k) && typeof row[k] === 'number');
  const min = keys.find((k) => /min|from|low/i.test(k));
  const max = keys.find((k) => /max|to|high/i.test(k));
  return { min, max };
}

export async function widenAgePrefs(page: Page): Promise<AgePrefs> {
  const api = await captureApi(page, '/map');
  const res = await restGet(api, `profiles?id=eq.${api.userId}&select=*`);
  expect(res.ok(), `profiles: ${await res.text()}`).toBeTruthy();
  const row: Row = (await res.json())[0];
  const { min, max } = ageKeys(row);
  if (!min || !max) throw new Error(`Не найдены колонки возрастного фильтра в profiles (${Object.keys(row).join(', ')}) — уточнить и поправить ageKeys`);
  const original: Row = { [min]: row[min], [max]: row[max] };
  const patch = await page.request.patch(`${api.base}/rest/v1/profiles?id=eq.${api.userId}`, {
    headers: { apikey: api.apikey, Authorization: api.auth, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
    data: { [min]: 18, [max]: 99 },
    failOnStatusCode: false,
  });
  expect(patch.ok(), `расширение фильтра: ${await patch.text()}`).toBeTruthy();
  return { api, original };
}

export async function restoreAgePrefs(p: AgePrefs | undefined) {
  if (!p) return;
  const res = await p.api.page.request.patch(`${p.api.base}/rest/v1/profiles?id=eq.${p.api.userId}`, {
    headers: { apikey: p.api.apikey, Authorization: p.api.auth, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
    data: p.original,
    failOnStatusCode: false,
  });
  expect(res.ok(), `возврат фильтра ${JSON.stringify(p.original)}: ${await res.text()}`).toBeTruthy();
}
